from content_common import *
lesson('mat-calculo','Extremos com restrições','Derivada nula dá candidato; o intervalo e a comparação dos valores decidem o extremo global.', ['A derivada informa a taxa de variação. Em um intervalo fechado, o máximo pode estar em um ponto crítico interno ou em uma das extremidades. Resolver apenas f′(x)=0 não termina o problema.','Para quadráticas, o sinal do coeficiente de x² indica a concavidade. Uma parábola voltada para baixo tem vértice de máximo no domínio real, mas o vértice pode ficar fora do intervalo permitido.'], 'Para g(x)=−x²+4x em [0,3], g′(x)=−2x+4. O candidato interno é x=2. Compare g(0)=0, g(2)=4 e g(3)=3: máximo 4 em x=2.', ['Identifique o domínio permitido.','Calcule a derivada e os candidatos internos.','Inclua os extremos do intervalo.','Compare os valores da função, não os da derivada.'], 'Máximo da função e ponto onde ele ocorre são respostas diferentes.', 'Edital — Matemática I.1')
pair('Matemática','Otimização em intervalo','mat-calculo',case('Uma medida de desempenho é f(x)=−x²+8x−7, com 0≤x≤3. O valor máximo de f nesse intervalo e o ponto em que ocorre são, respectivamente:', ['8 e x=3.','9 e x=4.','3 e x=8.','−7 e x=0.','9 e x=3.'], 'O vértice x=4 está fora do intervalo. Como f′(x)=8−2x>0 em [0,3], o máximo permitido ocorre em x=3: −9+24−7=8.', ['Usa o máximo irrestrito fora do domínio.','Troca ponto e valor e viola o domínio.','Esse é o valor na extremidade inferior.','Usa o valor do vértice com outro ponto.'],check={'kind':'quadratic','coeff':[-1,8,-7],'interval':[0,3],'max':[3,8]}),case('O custo C(x)=x²−10x+31 deve ser minimizado sob a restrição 1≤x≤4. O custo mínimo admissível é:', ['7, obtido em x=4.','6, obtido em x=5.','22, obtido em x=1.','4, obtido em x=7.','6, obtido em x=4.'], 'C′(x)=2x−10 é negativa em [1,4], logo o custo cai até x=4. C(4)=16−40+31=7; o vértice x=5 é inviável.', ['O ponto x=5 viola a restrição.','É o custo no limite inferior, maior que em x=4.','Troca custo e decisão, além de sair do intervalo.','Combina o mínimo irrestrito com ponto restrito.'],check={'kind':'quadratic','coeff':[1,-10,31],'interval':[1,4],'min':[4,7]}))
lesson('mat-integral','Integrais, área e variação acumulada','A integral definida acumula valores com sinal; área geométrica exige cuidado quando a função troca de sinal.', ['Uma primitiva F satisfaz F′=f. Pelo teorema fundamental, a integral de a até b é F(b)−F(a). Para potências, uma primitiva de xⁿ é xⁿ⁺¹/(n+1), quando n≠−1.','Se f fica negativa em parte do intervalo, essa região contribui negativamente para a integral. Para área total entre curva e eixo, separe o intervalo nas raízes e some os módulos das áreas.'], 'Para f(x)=x−1 em [0,2], a primitiva é x²/2−x. A integral total é 0, pois −1/2 e +1/2 se cancelam. A área geométrica total é 1.', ['Encontre as raízes dentro do intervalo.','Determine o sinal em cada trecho.','Calcule F(b)−F(a) por trecho.','Decida se o comando pede saldo com sinal ou área total.'], 'Integral igual a zero não significa ausência de área.', 'Edital — Matemática I.1')
pair('Matemática','Integral versus área','mat-integral',case('Para f(x)=x−2 no intervalo [0,4], a integral definida e a área geométrica entre o gráfico e o eixo x são, respectivamente:', ['0 e 4.','4 e 0.','0 e 0.','4 e 4.','−4 e 4.'], 'Há dois triângulos de base 2 e altura 2, cada um com área 2. Um fica abaixo e outro acima do eixo: integral −2+2=0; área 2+2=4.', ['Inverte saldo e área.','Ignora as regiões não nulas.','Não considera o sinal negativo no primeiro trecho.','Soma as contribuições como se ambas fossem negativas.']),case('Uma taxa líquida é r(t)=2t−2, para 0≤t≤3. A variação acumulada líquida e a soma das magnitudes das variações negativa e positiva são:', ['3 e 5.','5 e 3.','3 e 3.','−1 e 4.','9 e 5.'], 'A taxa zera em 1. A integral em [0,1] é −1; em [1,3], 4. O saldo é 3 e a soma dos módulos é 5.', ['Inverte saldo e magnitude.','Desconsidera o trecho negativo na área total.','Apresenta apenas os valores de trechos separados.','Integra 2t sem subtrair a contribuição de −2.']))
lesson('mat-linear','Matrizes e composição de transformações','Em BA, aplique A primeiro e B depois ao vetor coluna.', ['Uma matriz transforma vetores por combinações lineares. Para obter cada coordenada de Av, faça o produto escalar da linha correspondente de A com v. A ordem importa: em geral, AB≠BA.','Se Av=λv para v≠0, v é autovetor e λ é autovalor. A direção é preservada, possivelmente com inversão de sentido. Não basta uma coordenada ter sido multiplicada por λ: todas precisam obedecer à mesma escala.'], 'Se A=diag(2,1) e B troca as duas coordenadas, para v=(1,3) temos Av=(2,3) e BAv=(3,2). Já Bv=(3,1) e ABv=(6,1).', ['Escreva o vetor como coluna.','Comece pela matriz mais próxima do vetor.','Calcule cada linha vezes o vetor.','Para autovetor, compare todas as coordenadas com λv.'], 'Um vetor com coordenada zero continua podendo ser autovetor; o vetor nulo é excluído da definição.', 'Edital — Matemática I.2')
pair('Matemática','Composição matricial','mat-linear',case('Se A=[[1,1],[0,1]], B=[[2,0],[0,3]] e v=(1,2) é vetor coluna, o vetor BAv é:', ['(6,6).','(8,6).','(3,2).','(2,6).','(6,4).'], 'Primeiro Av=(1+2,2)=(3,2). Depois B(3,2)=(6,6). Aplicar B antes de A produziria outro resultado.', ['É ABv: Bv=(2,6) e A(2,6)=(8,6).','Calcula apenas Av e deixa de aplicar a transformação B ao resultado.','Calcula Bv, omitindo a transformação A que deve ser aplicada primeiro.','Aplica incorretamente fator 2 à segunda coordenada.'],check={'kind':'matrix','A':[[1,1],[0,1]],'B':[[2,0],[0,3]],'v':[1,2],'expected':[6,6]}),case('Para A=[[3,1],[0,2]], qual par (v,λ) satisfaz Av=λv?', ['v=(−1,1), λ=2.','v=(1,1), λ=2.','v=(0,1), λ=2.','v=(1,0), λ=2.','v=(−1,1), λ=3.'], 'A(−1,1)=(−2,2)=2(−1,1). A igualdade vale para ambas as coordenadas.', ['A(1,1)=(4,2), que não é 2(1,1).','A(0,1)=(1,2), não (0,2).','A(1,0)=(3,0), com autovalor 3.','A escala do vetor apresentado é 2, não 3.'],check={'kind':'eigen','A':[[3,1],[0,2]],'v':[-1,1],'lambda':2}))
lesson('mat-normas','Produto escalar e normas','Produto escalar mede alinhamento; norma mede tamanho. Não são a mesma operação.', ['Para u=(u₁,u₂) e v=(v₁,v₂), u·v=u₁v₁+u₂v₂. Se ambos são não nulos, produto zero indica ortogonalidade. A norma L1 é a soma dos módulos; L2 é a raiz da soma dos quadrados.','A distância entre dois pontos é a norma de sua diferença, não a diferença entre suas normas. Um vetor pode ter norma alta e produto escalar zero com outro.'], 'Para u=(−3,4), ||u||₁=3+4=7 e ||u||₂=√(9+16)=5. Se v=(4,3), u·v=−12+12=0.', ['Distinga vetor, norma e produto escalar.','Use módulos na L1 e quadrados na L2.','Para distância, calcule primeiro u−v.','Cheque se o comando pede valor ou relação geométrica.'], 'A raiz da soma dos quadrados não é a soma dos módulos.', 'Edital — Matemática I.2')
pair('Matemática','Distância e ortogonalidade','mat-normas',case('Para u=(1,−2) e v=(3,−1), a distância L1 entre u e v e o produto escalar u·v são, respectivamente:', ['3 e 5.','1 e 5.','√5 e 5.','3 e −5.','5 e 3.'], 'u−v=(−2,−1), cuja norma L1 é 2+1=3. Já u·v=1·3+(−2)·(−1)=5.', ['Usa diferença de normas L1 em lugar da norma da diferença.','É a distância L2, não L1.','Erra o sinal do produto de dois negativos.','Troca as operações.']),case('Para u=(2,−1,2) e v=(1,2,0), é correto afirmar que', ['u e v são ortogonais e ||u||₂=3.','u e v são ortogonais e ||u||₂=5.','u e v não são ortogonais e ||u||₂=3.','u e v são paralelos e ||u||₁=3.','u·v=4 e ||u||₂=3.'], 'u·v=2−2+0=0, então são ortogonais. ||u||₂=√(4+1+4)=3.', ['5 é a norma L1 de u.','O produto escalar é zero.','Não são paralelos e L1 vale 5.','O produto escalar foi somado com sinal errado.']))
lesson('mat-parcial','Derivadas parciais e gradiente','Na derivada parcial em x, trate y como constante; o gradiente reúne todas as derivadas parciais.', ['Em f(x,y), ∂f/∂x mede a variação ao mudar x mantendo y fixo. Um termo como xy vira y nessa derivada; um termo apenas em y vira zero.','O gradiente ∇f=(∂f/∂x,∂f/∂y) aponta a direção de maior crescimento local no espaço euclidiano. Uma atualização de descida usa θ_novo=θ−η∇f(θ), com η>0.'], 'Se g(x,y)=x²+3xy, então ∂g/∂x=2x+3y e ∂g/∂y=3x. Em (1,2), ∇g=(8,3). Com η=0,1, um passo resulta em (0,2;1,7).', ['Escolha a variável da derivação.','Congele as demais.','Avalie o gradiente no ponto antigo.','Subtraia η vezes esse gradiente em todas as coordenadas.'], 'Atualizar uma coordenada antes de calcular a outra muda o algoritmo se o enunciado pede atualização simultânea.', 'Edital — Matemática I.1 e Ciência de Dados 3')
pair('Matemática','Gradiente e atualização','mat-parcial',case('Para f(x,y)=x²+xy+2y², um passo simultâneo de descida do gradiente a partir de (1,1), com taxa 0,1, resulta em:', ['(0,7; 0,5).','(1,3; 1,5).','(0,8; 0,6).','(0,7; 0,53).','(0,3; 0,5).'], '∂f/∂x=2x+y=3 e ∂f/∂y=x+4y=5 no ponto inicial. Subtraindo 0,1(3,5) de (1,1), obtém-se (0,7;0,5).', ['Faz subida, somando o gradiente.','Ignora o termo cruzado xy.','Recalcula a segunda derivada após mudar x, contrariando a simultaneidade.','Confunde o deslocamento de x com o novo x.'],check={'kind':'gradient','point':[1,1],'gradient':[3,5],'eta':0.1,'expected':[0.7,0.5]}),case('Para g(x,y)=3x²−2xy+y², o gradiente em (1,2) e a direção de descida dada pelo seu negativo são:', ['(2,2) e (−2,−2).','(6,4) e (−6,−4).','(2,2) e (2,2).','(−2,−2) e (2,2).','(4,2) e (−4,−2).'], '∂g/∂x=6x−2y=2 e ∂g/∂y=−2x+2y=2. A direção negativa é (−2,−2).', ['Ignora o termo cruzado nas duas derivadas.','Repete o gradiente em vez de negá-lo.','Inverte gradiente e negativo.','Calcula incorretamente a primeira derivada.']))
lesson('est-bayes','Condicional, base e Bayes','Em P(A|B), o universo passa a ser B. O denominador precisa contar todas as formas de B acontecer.', ['P(A|B)=P(A∩B)/P(B), desde que P(B)>0. Trocar A e B muda a pergunta. Quando B pode surgir por grupos distintos, some as contribuições de todos os grupos para formar o denominador.','Bayes combina frequência inicial e taxa dentro do grupo: P(A|B)=P(B|A)P(A)/P(B). Uma taxa alta em um grupo pequeno não garante que ele predomine entre os casos observados.'], 'Duas linhas produzem 80% e 20% das peças, com defeito de 1% e 4%. Em 10.000 peças: 80 defeitos da primeira e 80 da segunda. Entre as 160 defeituosas, metade veio da segunda. A taxa de 4% não é a resposta posterior.', ['Imagine uma população conveniente, como 10.000 itens.','Distribua os itens pelas frequências iniciais.','Aplique a taxa dentro de cada grupo.','Some os casos do evento observado.','Divida a contribuição do grupo pedido pelo total observado.'], 'Usar só a taxa de defeito ignora o tamanho inicial do grupo.', 'Edital — Estatística II.1 e II.2')
pair('Estatística','Inferência bayesiana','est-bayes',case('As linhas A e B produzem 60% e 40% das peças. As taxas de defeito são 2% e 5%, respectivamente. Uma peça escolhida ao acaso é defeituosa. A probabilidade de ter vindo de B é:', ['62,5%.','40%.','5%.','71,4%.','2%.'], 'As contribuições são 0,60·0,02=0,012 e 0,40·0,05=0,020. Logo P(B|defeito)=0,020/0,032=0,625.', ['É a probabilidade inicial, antes de observar o defeito.','É P(defeito|B), com condicionamento invertido.','Resulta de 5/(2+5), ignorando os tamanhos dos grupos.','É a taxa de defeito de A.'],check={'kind':'bayes','prior':[0.6,0.4],'rates':[0.02,0.05],'target':1,'expected':0.625}),case('Um classificador marca 90% dos itens irregulares e marca indevidamente 10% dos regulares. Apenas 20% dos itens são irregulares. Entre os itens marcados, a proporção de irregulares é:', ['9/13, aproximadamente 69,23%.','90%.','80%.','18%.','2/3, aproximadamente 66,67%.'], 'Em 100 itens: 20 são irregulares e 18 são marcados; dos 80 regulares, 8 são marcados. Entre 26 marcados, 18 são irregulares: 18/26=9/13.', ['É a sensibilidade P(marcado|irregular), não a posterior.','É a frequência de regulares na população.','É a probabilidade conjunta, antes da divisão pelos marcados.','Não corresponde à razão 18/26.'],check={'kind':'bayes','prior':[0.2,0.8],'rates':[0.9,0.1],'target':0,'expected':9/13}))
lesson('est-indep','Independência não é exclusão','Eventos independentes podem acontecer juntos; eventos disjuntos não acontecem juntos.', ['Independência exige P(A∩B)=P(A)P(B). Se P(B)>0, isso equivale a P(A|B)=P(A). Disjunção exige P(A∩B)=0.','Para “ao menos um”, muitas vezes é mais simples calcular 1−P(nenhum). Só multiplique probabilidades de eventos separados quando houver independência ou probabilidades condicionais adequadas.'], 'Se eventos independentes têm probabilidades 0,2 e 0,5, a interseção vale 0,1, não zero. Em três tentativas independentes com sucesso 0,2, P(ao menos um)=1−0,8³=0,488.', ['Identifique se o comando pede interseção, união ou complemento.','Verifique o que foi dado sobre dependência.','Use inclusão-exclusão: P(A∪B)=P(A)+P(B)−P(A∩B).'], 'A palavra “diferentes” não implica independência.', 'Edital — Estatística II.1')
pair('Estatística','Independência e união','est-indep',case('P(A)=0,4, P(B)=0,5 e P(A∪B)=0,7. Nessas condições:', ['A e B são independentes e P(A|B)=0,4.','A e B são disjuntos e P(A|B)=0.','A e B são dependentes porque a interseção é positiva.','P(A∩B)=0,9 e P(A|B)=1,8.','A e B são independentes e P(A|B)=0,5.'], 'P(A∩B)=0,4+0,5−0,7=0,2=0,4·0,5. São independentes; P(A|B)=0,2/0,5=0,4.', ['A interseção é 0,2, não zero.','Interseção positiva não impede independência.','Ignora a subtração da união e produz probabilidade impossível.','Confunde P(A) com P(B) no resultado condicional.']),case('Três testes independentes detectam uma falha com probabilidade 0,6 cada um. A probabilidade de ao menos um detectar a falha é:', ['0,936.','0,216.','0,600.','0,784.','0,064.'], 'O complemento é nenhum detectar: 0,4³=0,064. Assim, 1−0,064=0,936.', ['É a probabilidade de todos detectarem.','É a chance em apenas um teste.','É 1−0,6³, complemento de todos detectarem.','É nenhum detectar, sem aplicar o complemento.']))
lesson('est-variancia','Esperança, variância e transformação','Variância mede dispersão ao quadrado. Somar uma constante muda a média, mas não espalha os valores.', ['Para variável discreta, calcule E(X)=Σx·P(X=x). Depois E(X²)=Σx²·P(X=x). A variância é E(X²)−[E(X)]²; o desvio-padrão é sua raiz.','Para Y=aX+b, E(Y)=aE(X)+b e Var(Y)=a²Var(X). A constante b desloca todos os valores igualmente, portanto não altera a dispersão.'], 'Se X vale 0 ou 2 com probabilidades 1/2 e 1/2: E(X)=0·1/2+2·1/2=1; E(X²)=0²·1/2+2²·1/2=2; Var(X)=2−1²=1. Para Y=3X+4, E(Y)=7, Var(Y)=9 e DP(Y)=3.', ['Faça colunas x, P(x), x·P(x) e x²·P(x).','Some as duas últimas colunas.','Subtraia o quadrado da média da média dos quadrados.','Aplique a transformação e só depois extraia a raiz se pedirem DP.'], 'E(X²) não é [E(X)]². Multiplicar X por a multiplica a variância por a².', 'Edital — Estatística II.1')
pair('Estatística','Variância de variável transformada','est-variancia',case('X assume 0, 1 e 2 com probabilidades 0,2; 0,5; 0,3. Para Y=2X−1, a variância de Y é:', ['1,96.','0,98.','0,49.','0,96.','1,20.'], 'E(X)=1,1; E(X²)=1,7; Var(X)=1,7−1,21=0,49. Como Y=2X−1, Var(Y)=4·0,49=1,96.', ['Multiplica a variância por 2, não por 2².','É a variância de X, sem transformação.','Subtrai a constante 1 da variância transformada, embora translação não altere variância.','É E(Y), não sua variância.'],check={'kind':'discrete','x':[0,1,2],'p':[0.2,0.5,0.3],'a':2,'b':-1,'variance':1.96}),case('E(X)=4 e E(X²)=20. Para Y=−3X+2, o desvio-padrão de Y é:', ['6.','−6.','12.','36.','4.'], 'Var(X)=20−16=4 e DP(X)=2. DP(Y)=|−3|·2=6; equivalentemente Var(Y)=9·4=36 e sua raiz é 6.', ['Desvio-padrão nunca é negativo.','Multiplica a variância por 3 e confunde com DP.','É a variância de Y, não o DP.','É a variância de X.']))
lesson('est-cov','Covariância de combinações','A variância de uma soma inclui um termo de covariância; ele não desaparece sem justificativa.', ['Var(aX+bY)=a²Var(X)+b²Var(Y)+2abCov(X,Y). Se o coeficiente de uma variável for negativo, o termo cruzado também muda de sinal.','Correlação é covariância dividida pelo produto dos desvios-padrão, quando ambos são positivos. Covariância zero não prova independência em geral; em uma normal conjunta, a conclusão vale.'], 'Se Var(X)=1, Var(Y)=4 e Cov(X,Y)=1, Var(X+Y)=1+4+2=7 e Var(X−Y)=1+4−2=3. A correlação é 1/(1·2)=0,5.', ['Extraia variâncias e covariância da matriz ou enunciado.','Identifique os coeficientes a e b.','Calcule os termos quadráticos e o cruzado.','Confira se a variância final é não negativa.'], 'Covariância tem escala; correlação é adimensional e fica entre −1 e 1.', 'Edital — Estatística II.1 e II.2')
pair('Estatística','Matriz de covariância','est-cov',case('A matriz de covariância de (X,Y) é [[4,1],[1,9]]. A variância de 2X−Y é:', ['21.','25.','29.','13.','6.'], 'Var(2X−Y)=4·4+9+2·2·(−1)·1=16+9−4=21.', ['Omite o termo cruzado.','Soma o termo cruzado com sinal positivo.','Não eleva o coeficiente de X ao quadrado.','Combina entradas da matriz como se fossem desvios-padrão.']),case('Var(X)=9, Var(Y)=4 e Corr(X,Y)=−0,5. A covariância e a variância de X+Y são:', ['−3 e 7.','−0,5 e 12.','−6 e 1.','3 e 19.','−3 e 13.'], 'Cov=−0,5·3·2=−3. Var(X+Y)=9+4+2(−3)=7.', ['Usa correlação como se fosse covariância.','Multiplica por uma escala incorreta.','Perde o sinal negativo.','Omite a covariância na soma.']))
lesson('est-inferencia','Erro-padrão e intervalo de confiança','O desvio-padrão dos dados e o erro-padrão da média descrevem dispersões diferentes.', ['Em amostra aleatória independente com variância finita, a média amostral tem variância σ²/n e erro-padrão σ/√n. Para n suficientemente grande, o TLC fundamenta aproximação normal da média; não torna necessariamente os dados individuais normais.','Um IC frequentista de 95% usa um procedimento que cobre o parâmetro fixo em 95% das repetições sob as hipóteses do modelo. Não quer dizer que 95% dos indivíduos estejam no intervalo da média.'], 'Se σ=12 e n=36, EP=12/6=2. Com média 50 e z≈1,96, o IC é 50±3,92. Para cortar a margem pela metade, mantendo σ e confiança, multiplique n por 4.', ['Identifique se a pergunta trata de dados ou da média.','Use √n no denominador do erro-padrão.','Separe estimativa pontual de margem.','Interprete a cobertura do procedimento, sem atribuí-la aos indivíduos.'], 'Dobrar n reduz a margem por √2; não a divide por 2.', 'Edital — Estatística II.2')
pair('Estatística','TLC e tamanho amostral','est-inferencia',case('Mantendo o mesmo nível de confiança e o desvio-padrão populacional, deseja-se reduzir de 6 para 2 a margem de erro de um IC para a média. Se a amostra inicial tinha 100 observações independentes, o novo tamanho deve ser:', ['900.','300.','600.','400.','1.800.'], 'A margem é proporcional a 1/√n. Dividi-la por 3 exige multiplicar n por 3²=9: 900.', ['Multiplica por 3 em vez de 9.','Usa uma relação linear incompatível.','Quadruplica, o que apenas divide a margem por 2.','Duplica o tamanho necessário sem justificativa.']),case('Uma amostra aleatória independente de tamanho 64 vem de população com média μ e desvio-padrão 16. A média amostral tem:', ['média μ e erro-padrão 2.','média μ/64 e erro-padrão 16.','média μ e variância 2.','média 64μ e erro-padrão 128.','distribuição exatamente normal para qualquer população, por definição.'], 'E(X̄)=μ e EP(X̄)=16/√64=2. A variância da média é 4. A normalidade é exata para população normal e aproximada em condições do TLC.', ['A média é não viesada para μ e sua dispersão diminui.','Confunde erro-padrão com variância.','Usa características de soma e ainda escala incorretamente o DP.','O TLC não assegura normalidade exata para toda população finita.']))
lesson('est-mle','Verossimilhança e teste de hipótese','Verossimilhança compara parâmetros à luz dos dados observados; p-valor não é a probabilidade de a hipótese ser verdadeira.', ['Para observações Bernoulli independentes, a verossimilhança é pᵏ(1−p)ⁿ⁻ᵏ, em que k é o número de sucessos. O máximo ocorre em p̂=k/n, incluindo os casos de fronteira k=0 ou k=n.','Em teste frequentista, o p-valor mede, sob H0 e o modelo do teste, a probabilidade de resultado ao menos tão incompatível com H0 quanto o observado. Não é P(H0|dados). Rejeitar H0 também não mede o tamanho prático do efeito.'], 'Em 20 observações Bernoulli com 7 sucessos, p̂=7/20=0,35. Em outro estudo, p=0,03 leva à rejeição com α=0,05, mas não significa “3% de chance de H0 ser verdadeira”.', ['Identifique modelo e parâmetro.','Escreva a função dos dados que depende do parâmetro.','Para teste, localize a hipótese nula e α.','Separe evidência estatística, tamanho do efeito e probabilidade posterior.'], 'Não aceitar H0 não é provar H0; p pequeno não garante relevância prática.', 'Edital — Estatística II.2')
pair('Estatística','Máxima verossimilhança','est-mle',case('Em 50 observações Bernoulli independentes, ocorreram 18 sucessos. O estimador de máxima verossimilhança de p e a forma da verossimilhança, desprezando fatores constantes em p, são:', ['0,36 e p¹⁸(1−p)³².','0,64 e p¹⁸(1−p)³².','0,36 e p³²(1−p)¹⁸.','18 e p¹⁸(1−p)⁵⁰.','0,18 e p⁵⁰(1−p)¹⁸.'], 'Cada sucesso contribui p e cada fracasso 1−p. São 18 e 32, respectivamente; o máximo é a proporção 18/50=0,36.', ['É a proporção de fracassos.','Troca os expoentes dos tipos de observação.','p deve estar entre 0 e 1 e o total de fracassos não é 50.','Divide por 100 e atribui expoentes incorretos.']),case('Um teste produz p-valor 0,02, com nível de significância previamente fixado em 0,05. A interpretação correta é:', ['rejeita-se H0; o p-valor não é a probabilidade posterior de H0 ser verdadeira.','H0 tem probabilidade de 2% de ser verdadeira, independentemente de informação anterior.','há 98% de probabilidade de o efeito ser grande na prática.','a amostra contém exatamente 2% de observações incompatíveis com H0.','não se rejeita H0 porque 0,02 é menor que 0,05.'], 'Como p<α, rejeita-se H0 pelo critério fixado. O valor é calculado sob H0, não atribui uma probabilidade posterior a ela.', ['Inverte o condicionamento.','Significância não mede magnitude prática.','Não é uma fração das observações da amostra.','Inverte a regra de decisão.']))
